#!/usr/bin/env python3
"""Original runtime directory-command SH-2 guest. MIT: adjacent LICENSE.

ST-162 §§3.4/6.2: a mounted medium is supplied by the test; every command,
completion poll, response read and result write is an executed SH-2 instruction.
"""
import argparse
import hashlib
from pathlib import Path
import struct
from build_cd_drive import command, store
from build_scu import assembler

HERE = Path(__file__).resolve().parent


def build():
    def wait(name):
        return f'load 0x25890008,r1\nload 0x200,r2\n{name}:\nmov.w @r1,r0\ntst r2,r0\nbt {name}\n'
    source = store(0x25890008, 0xFDFF) + command([0x7000, 0, 0xFF, 0xFFFF], 'change_directory', 0x06009000)
    source += wait('root_efls') + store(0x25890008, 0xFDFF)
    source += command([0x7100, 0, 0xFF, 0xFFFF], 'read_directory', 0x06009010)
    source += 'load 0x06009010,r1\nmov.l @r1,r0\nload 0xFF00,r2\ncmp/eq r2,r0\nbt no_table\n'
    source += wait('read_efls') + 'no_table:\n'
    source += command([0x7200, 0, 0, 0], 'scope', 0x06009020)
    source += 'load 0x06009030,r1\nload 0x600d,r0\nmov.l r0,@r1\nsleep\n'
    rom = bytearray(524288)
    struct.pack_into('>II', rom, 0, 0x200, 0x06100000)
    code = assembler.assemble(source, base=0x200)
    rom[0x200:0x200 + len(code)] = code
    lines = ['# Original runtime directory guest. MIT: adjacent LICENSE.',
             '# Generated by build_cd_directory.py; unspecified bytes are zero.']
    for address in range(0, len(rom), 16):
        block = rom[address:address + 16]
        if any(block):
            lines.append(f'{address:04X} ' + ' '.join(f'{w:04X}' for w in struct.unpack('>8H', block)))
    return '\n'.join(lines) + '\n', hashlib.sha256(rom).hexdigest()


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    text, digest = build()
    path = HERE / 'cd-directory.hex'
    if args.check:
        assert path.read_text() == text, 'Rebuild cd-directory.hex'
    else:
        path.write_text(text)
    print(f'{"Verified" if args.check else "Built"} cd-directory.hex; expanded ROM SHA-256 {digest}')
